MAP
    NAME "SS_MAP_MCIR_EFICIENCIA_MES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_sector_eficiencia_mes.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_MCIR_EFICIENCIA_MES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        INCLUDE 'includes/conexion.map'
        DATA "geometry from (select a.gid, a.geometry, b.eficiencia,b.color from subcircuitos a,sectores_mes_eficiencia b WHERE a.gid = b.gid) as tmp using unique gid using srid=32614"
        STATUS DEFAULT
        TYPE POLYGON
        LABELITEM "eficiencia"
        CLASSITEM "color"
        CLASS
            NAME "> 100"
            EXPRESSION "A"
            STYLE
                COLOR 0 0 255
                OUTLINECOLOR 0 0 0
                SIZE 16
            END #STYLE
            LABEL
                SIZE 19
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
                TYPE TRUETYPE
                OFFSET 0 20
                FONT "ARIAL"
            END #LABEL
        END #CLASS
        CLASS
            NAME ">= 67 y <= 100"
            EXPRESSION "V"
            STYLE
                SIZE 16
                COLOR 78 198 0
                OUTLINECOLOR 0 0 0
            END #STYLE
            LABEL
                SIZE 19
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
                TYPE TRUETYPE
                OFFSET 0 20
                FONT "ARIAL"
            END #LABEL
        END #CLASS
        CLASS
            NAME ">=66 y <67"
            EXPRESSION "N"
            STYLE
                SIZE 16
                COLOR 255 193 0
                OUTLINECOLOR 0 0 0
            END #STYLE
            LABEL
                SIZE 19
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
                TYPE TRUETYPE
                OFFSET 0 20
                FONT "ARIAL"
            END #LABEL
        END #CLASS
        CLASS
            NAME "<66"
            EXPRESSION "R"
            STYLE
                SIZE 16
                COLOR 255 0 0
                OUTLINECOLOR 0 0 0
            END #STYLE
            LABEL
                SIZE 19
                COLOR 0 0 0
                OUTLINECOLOR 254 254 254
                TYPE TRUETYPE
                OFFSET 0 20
                FONT "ARIAL"
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP